Exercise: Matching Brackets (matching-brackets)
Difficulty: 4/9

Instructions:
# Instructions

Given a string containing brackets `[]`, braces `{}`, parentheses `()`, or any combination thereof, verify that any and all pairs are matched and nested correctly.
Any other characters should be ignored.
For example, `"{what is (42)}?"` is balanced and `"[text}"` is not.


Starter file:
```zig
const std = @import("std");
const mem = std.mem;

pub fn isBalanced(allocator: mem.Allocator, s: []const u8) !bool {
    _ = allocator;
    _ = s;
    @compileError("please implement the isBalanced function");
}

```

Tests that will be run with `zig test`:
```zig
const std = @import("std");
const testing = std.testing;

const isBalanced = @import("matching_brackets.zig").isBalanced;

test "paired square brackets" {
    const actual = try isBalanced(testing.allocator, "[]");
    try testing.expect(actual);
}

test "empty string" {
    const actual = try isBalanced(testing.allocator, "");
    try testing.expect(actual);
}

test "unpaired brackets" {
    const actual = try isBalanced(testing.allocator, "[[");
    try testing.expect(!actual);
}

test "wrong ordered brackets" {
    const actual = try isBalanced(testing.allocator, "}{");
    try testing.expect(!actual);
}

test "wrong closing bracket" {
    const actual = try isBalanced(testing.allocator, "{]");
    try testing.expect(!actual);
}

test "paired with whitespace" {
    const actual = try isBalanced(testing.allocator, "{ }");
    try testing.expect(actual);
}

test "partially paired brackets" {
    const actual = try isBalanced(testing.allocator, "{[])");
    try testing.expect(!actual);
}

test "simple nested brackets" {
    const actual = try isBalanced(testing.allocator, "{[]}");
    try testing.expect(actual);
}

test "several paired brackets" {
    const actual = try isBalanced(testing.allocator, "{}[]");
    try testing.expect(actual);
}

test "paired and nested brackets" {
    const actual = try isBalanced(testing.allocator, "([{}({}[])])");
    try testing.expect(actual);
}

test "unopened closing brackets" {
    const actual = try isBalanced(testing.allocator, "{[)][]}");
    try testing.expect(!actual);
}

test "unpaired and nested brackets" {
    const actual = try isBalanced(testing.allocator, "([{])");
    try testing.expect(!actual);
}

test "paired and wrong nested brackets" {
    const actual = try isBalanced(testing.allocator, "[({]})");
    try testing.expect(!actual);
}

test "paired and wrong nested brackets but innermost are correct" {
    const actual = try isBalanced(testing.allocator, "[({}])");
    try testing.expect(!actual);
}

test "paired and incomplete brackets" {
    const actual = try isBalanced(testing.allocator, "{}[");
    try testing.expect(!actual);
}

test "too many closing brackets" {
    const actual = try isBalanced(testing.allocator, "[]]");
    try testing.expect(!actual);
}

test "early unexpected brackets" {
    const actual = try isBalanced(testing.allocator, ")()");
    try testing.expect(!actual);
}

test "early mismatched brackets" {
    const actual = try isBalanced(testing.allocator, "{)()");
    try testing.expect(!actual);
}

test "math expression" {
    const actual = try isBalanced(testing.allocator, "(((185 + 223.85) * 15) - 543)/2");
    try testing.expect(actual);
}

test "complex latex expression" {
    const s = "\\left(\\begin{array}{cc} \\frac{1}{3} & x\\\\ \\mathrm{e}^{x} &... x^2 \\end{array}\\right)";
    const actual = try isBalanced(testing.allocator, s);
    try testing.expect(actual);
}

test "maximum required level of nesting" {
    const s = "(((_[[[_{{{_()_}}}_]]]_)))";
    const actual = try isBalanced(testing.allocator, s);
    try testing.expect(actual);
}

```

```zig
const std = @import("std");
const mem = std.mem;

pub fn isBalanced(allocator: mem.Allocator, s: []const u8) !bool {
    var buf: []u8 = try allocator.alloc(u8, s.len);
    defer allocator.free(buf);
    var stackPos: usize = 0;
    for (s) |c| {
        switch (c) {
            '(', '{', '[' => {
                const expected = switch (c) {
                    '(' => ')',
                    '{' => '}',
                    '[' => ']',
                    else => unreachable,
                };
                if (stackPos >= buf.len) {
                    return false;
                }
                buf[stackPos] = expected;
                stackPos += 1;
            }
            ')', '}', ']' => {
                if (stackPos == 0) {
                    return false;
                }
                stackPos -= 1;
                if (buf[stackPos] != c) {
                    return false;
                }
            }
            else => {},
        }
    }
    return stackPos == 0;
}

```

